/**
 * V1.26 — autonomous, SOURCE-LINKED convoy guards and bandit raids.
 *
 * These are real worldAi parties: no fabricated BattleManager outcomes,
 * loot payouts or new quest-completion proofs are generated by NPC clashes.
 * Runtime WeakSets prevent an imported/save-cloned guard or bandit from
 * impersonating an active escort battle source.
 */
import { isLiveEscortParty, validEscortQuest } from './quest-caravan-escort.js';
import { isRuntimeRouteBandit } from './quest-route-recon.js';
import { validBanditRoute } from './quest-world-party-links.js';
import {
  recordEscortCargoRaid, returnGuardRecoveredEscortCargo,
  disposeLiveBanditCargo,
} from './quest-escort-cargo.js';

const runtimeGuards = new WeakSet();
const skirmishRecords = new WeakMap();
const distance = (a,b) => Math.hypot(a.x-b.x,a.y-b.y);
const finite = p => p && Number.isFinite(p.x) && Number.isFinite(p.y);
const clamp = (v,a,b) => Math.max(a, Math.min(b,v));

export function isRuntimeEscortGuard(guard) {
  return Boolean(guard && runtimeGuards.has(guard));
}

export function spawnEscortNpcGuards(caravan, parties) {
  if (!isLiveEscortParty(caravan) || !Array.isArray(parties)
    || !parties.includes(caravan) || caravan.alive === false) return [];
  const existing=parties.filter(p=>p?.escortGuardOf===caravan.id && p.alive!==false);
  if (existing.length) return existing.filter(isRuntimeEscortGuard);
  const guards=Array.from({length:3},(_,i)=>{
    const guard={
      id:`quest-escort-guard-${caravan.escortQuestId}-${i+1}`,
      escortGuardOf:caravan.id, escortQuestId:caravan.escortQuestId,
      routeId:caravan.routeId, kind:'escort_guard',
      encounterType:'caravan', factionId:'neutral',
      alive:true, x:caravan.x, y:caravan.y,
      targetX:caravan.x, targetY:caravan.y,
      homeCityId:caravan.homeCityId, radius:5, speed:0,
      hp:30, maxHp:30, attack:12,
    };
    runtimeGuards.add(guard);
    return guard;
  });
  parties.push(...guards);
  return guards;
}

export function activeEscortGuards(caravan, parties) {
  if (!isLiveEscortParty(caravan) || !Array.isArray(parties)) return [];
  return parties.filter(p=>p?.alive!==false && p.escortGuardOf===caravan.id
    && p.escortQuestId===caravan.escortQuestId && p.routeId===caravan.routeId
    && isRuntimeEscortGuard(p) && p.hp>0);
}

export function moveEscortGuards(caravan, parties, tileSize=32) {
  const guards=activeEscortGuards(caravan,parties);
  // Guard entities form a small formation around the convoy; they do not
  // masquerade as standard patrols, which use instant bandit-purge rules.
  guards.forEach((g,i)=>{
    const angle=(i * (2*Math.PI/3)) + Math.PI/2;
    const gap=Math.min(12,Math.max(5,tileSize*0.25));
    g.x=caravan.x+Math.cos(angle)*gap;
    g.y=caravan.y+Math.sin(angle)*gap;
    g.targetX=caravan.x;g.targetY=caravan.y;
  });
  return guards;
}

export function retireEscortNpcGuards(caravan,parties) {
  if (!Array.isArray(parties) || !caravan?.id) return 0;
  let removed=0;
  for(const p of parties){
    if(p?.escortGuardOf===caravan.id){
      if(p.alive!==false) removed++;
      p.alive=false;
    }
  }
  return removed;
}

export function runEscortNpcSkirmish({
  caravan, quest, parties, worldState, tradeRoutes,
  currentDay, dtSec,
}={}) {
  const route=validEscortQuest(quest,worldState,tradeRoutes,currentDay);
  if(!isLiveEscortParty(caravan) || caravan?.alive===false
    || caravan?.kind!=='caravan' || !route?.road
    || quest?.id !== caravan.escortQuestId
    || route.routeId !== caravan.routeId
    || String(route.from.id) !== String(caravan.homeCityId)
    || String(route.to.id) !== String(caravan.escortDestinationCityId)
    || !Array.isArray(parties) || !parties.includes(caravan)
    || !Number.isFinite(dtSec) || dtSec<=0 || dtSec>1)
    return {status:'invalid'};
  const radius=Math.max(64,Number(worldState?.tileSize||32)*2.5);
  const threats=parties.filter(b=>b?.kind==='bandit' && b.alive!==false
    && b.factionId==='bandits' && b.routeId===caravan.routeId
    && finite(b) && distance(b,caravan)<=radius
    && isRuntimeRouteBandit(b)
    && validBanditRoute(b,worldState,tradeRoutes)?.road)
    .sort((a,b)=>String(a.id).localeCompare(String(b.id),'en'));
  const guards=moveEscortGuards(caravan,parties,Number(worldState?.tileSize||32));
  caravan.escortGuardCount=guards.length;
  if (!threats.length) return {status:'clear',guards:guards.length,threats:0};
  if(!caravan.escortStarted || caravan.escortArrived || caravan.escortFailed){
    return {status:'waiting',guards:guards.length,threats:threats.length};
  }
  let record=skirmishRecords.get(caravan);
  if(!record){
    record={guardClock:0,banditClock:0,banditHp:new WeakMap()};
    skirmishRecords.set(caravan,record);
  }
  record.guardClock+=dtSec;
  record.banditClock+=dtSec;
  // Deterministic strikes make world skirmishes reproducible and bounded.
  // A bandit stays a genuine world entity until its actual NPC HP is lost.
  let attacks=0,raids=0;
  const bandit=threats[0];
  const sourceHp=record.banditHp.get(bandit)??110;
  let hp=sourceHp;
  let living=guards;
  while(record.guardClock>=0.8 && living.length && hp>0 && attacks<3){
    record.guardClock-=0.8;
    hp-=living.reduce((n,g)=>n+Math.max(1,Number(g.attack)||1),0);
    attacks++;
  }
  record.banditHp.set(bandit,Math.max(0,hp));
  if(hp<=0){
    // The verified live skirmish has ACTUALLY killed this exact road bandit.
    // Only its sourced cargo stolen from this convoy returns to the manifest.
    bandit.alive=false;
    const returnedCargo=returnGuardRecoveredEscortCargo({
      caravan,bandit,quest,worldState,tradeRoutes,currentDay,
    });
    // Other caravans may also have been robbed by the same live bandit.
    // Their remaining goods are classified as unrecovered, NOT granted to
    // this convoy or to the player without a trusted recovery event.
    disposeLiveBanditCargo({bandit,reason:'escort_guard_kill'});
    caravan.escortDefended=(caravan.escortDefended||0)+1;
    record.guardClock=0;
    record.banditClock=0;
    return {status:'defended',guards:living.length,threats:0,attacks,raids,
      returnedCargo,returnedUnits:returnedCargo.reduce((n,r)=>n+r.qty,0)};
  }
  while(record.banditClock>=1.2 && raids<3){
    record.banditClock-=1.2;
    raids++;
    living=activeEscortGuards(caravan,parties);
    if(living.length){
      const target=living[0];
      target.hp=clamp(target.hp-18,0,target.maxHp);
      if(target.hp<=0) target.alive=false;
      // Even a guarded caravan may lose a little exposed cargo.
      caravan.escortCargo=clamp(caravan.escortCargo-2,0,caravan.escortCargoMax);
    } else {
      caravan.escortCargo=clamp(caravan.escortCargo-22,0,caravan.escortCargoMax);
      caravan.escortHull=clamp(caravan.escortHull-22,0,caravan.escortHullMax);
    }
  }
  // Real typed goods move to the live source bandit's session-only loot.
  // The existing scalar HUD/HP model remains unchanged for old quests.
  if(raids>0) recordEscortCargoRaid({
    caravan, bandit, remainingPercent:caravan.escortCargo,
  });
  const remaining=activeEscortGuards(caravan,parties).length;
  caravan.escortGuardCount=remaining;
  if(caravan.escortCargo<=0 || caravan.escortHull<=0){
    caravan.escortFailed=true;
    return {status:'raided',guards:remaining,threats:threats.length,
      cargo:caravan.escortCargo,hull:caravan.escortHull,attacks,raids};
  }
  return {status:'skirmishing',guards:remaining,threats:threats.length,
    cargo:caravan.escortCargo,hull:caravan.escortHull,attacks,raids};
}
